DROP TABLE IF EXISTS `auditoria_datos_hora`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `auditoria_datos_hora` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_maestro` int NOT NULL COMMENT 'ID de la jornada',
  `hora_editada` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'La hora que modificaron',
  `nomina_editor` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Quién hizo el cambio',
  `fecha_edicion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Cuándo lo modificaron',
  `json_antes` json NOT NULL COMMENT 'Respaldo de los datos originales',
  `json_despues` json NOT NULL COMMENT 'Los datos nuevos con error',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=188 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
