--
-- Table structure for table `datos_hora`
--

DROP TABLE IF EXISTS `datos_hora`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `datos_hora` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_maestro` int NOT NULL,
  `hora` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_actualizacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `estado` enum('Abierto','Cerrado','Pendiente') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Abierto',
  `nomina_captura` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `motivo_retardo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `autorizado_por` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hora_exacta` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `coc_temp_entrada` decimal(5,2) DEFAULT NULL,
  `coc_temp_salida` decimal(5,2) DEFAULT NULL,
  `estado_autorizacion` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `motivo_edicion` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_maestro_hora` (`id_maestro`,`hora`),
  CONSTRAINT `fk_maestro` FOREIGN KEY (`id_maestro`) REFERENCES `registro_maestro` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1837 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

