  `h2o2_clari` decimal(10,2) DEFAULT NULL,
  `h2o2_filtro` decimal(10,2) DEFAULT NULL,
  `hso2_churro` decimal(10,2) DEFAULT NULL,
  `solidos_agua` decimal(10,2) DEFAULT NULL,
  `ce_agua` decimal(10,2) DEFAULT NULL,
  `ph_agua` decimal(10,2) DEFAULT NULL,
  `temp_con1` decimal(10,2) DEFAULT NULL,
  `temp_con2` decimal(10,2) DEFAULT NULL,
  `temp_con3` decimal(10,2) DEFAULT NULL,
  `temp_con4` decimal(10,2) DEFAULT NULL,
  `temp_con5` decimal(10,2) DEFAULT NULL,
  `churro_ph` decimal(10,2) DEFAULT NULL,
  `churro_solidos` decimal(10,2) DEFAULT NULL,
  `churro_acidez` decimal(10,2) DEFAULT NULL,
  `quimico_peroxido` decimal(10,2) DEFAULT NULL,
  `quimico_sanitizante` decimal(10,2) DEFAULT NULL,
  `quimico_otros` decimal(10,2) DEFAULT NULL,
  `temp_control_1` decimal(10,2) DEFAULT NULL,
  `temp_control_2` decimal(10,2) DEFAULT NULL,
  `temp_control_3` decimal(10,2) DEFAULT NULL,
  `temp_control_4` decimal(10,2) DEFAULT NULL,
  `temp_control_5` decimal(10,2) DEFAULT NULL,
  `churro_visco_verde` float DEFAULT NULL,
  `churro_visco_amarillo` float DEFAULT NULL,
  `churro_visco_azul` float DEFAULT NULL,
  `estado_fo_conc_final` int NOT NULL DEFAULT '0',
  `estado_fo_churro` int NOT NULL DEFAULT '0',
  `estado_fo_peroxidos` int NOT NULL DEFAULT '0',
  `estado_fo_agua` int NOT NULL DEFAULT '0',
  `estado_fo_temp` int NOT NULL DEFAULT '0',
  `churro_viscosidad` decimal(10,2) DEFAULT NULL,
