CREATE TABLE `datos_tanques` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_datos_hora` int NOT NULL COMMENT 'Relación con la hora de captura',
  `numero_tanque` int NOT NULL COMMENT 'Tanque del 1 al 5',
  `presion_entrada` decimal(5,2) DEFAULT NULL COMMENT 'Valor capturado por el operador',
  `cambio_pieza` tinyint(1) DEFAULT '0' COMMENT '0 = No, 1 = Sí (Aplica para Amarillo)',
  `ruta_foto` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Ruta donde se guardó en la NAS',
  `estado_fo` tinyint(1) DEFAULT '0' COMMENT 'Fuera de Operación',
  PRIMARY KEY (`id`),
  KEY `id_datos_hora` (`id_datos_hora`)
) ENGINE=MyISAM AUTO_INCREMENT=56 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
